// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	TTHeaderStreaming
	GRPCStreaming

	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	if tp == PurePayload {
		return "PurePayload"
	}

	// Map of all known flags in ascending order
	flags := []struct {
		value Protocol
		name  string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	var names []string
	remaining := tp

	for _, flag := range flags {
		if tp&flag.value == flag.value {
			names = append(names, flag.name)
			remaining &^= flag.value
		}
	}

	if len(names) == 0 || remaining != 0 {
		return Unknown
	}

	result := names[0]
	for i := 1; i < len(names); i++ {
		result += "|" + names[i]
	}
	return result
}

