// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

// Dump returns diagnostic information about the connection pool state.
// It provides a snapshot of active connections, their addresses, and state for debugging.
func (p *connPool) Dump() string {
	var result strings.Builder
	result.WriteString("ConnPool Dump:\n")
	result.WriteString(fmt.Sprintf("  RemoteService: %s\n", p.remoteService))
	result.WriteString(fmt.Sprintf("  PoolSize: %d\n", p.size))
	result.WriteString(fmt.Sprintf("  ShortConn: %v\n", p.connOpts.ShortConn))
	result.WriteString("  Connections:\n")

	p.conns.Range(func(key, value interface{}) bool {
		address := key.(string)
		trans := value.(*transports)
		result.WriteString(fmt.Sprintf("    Address: %s\n", address))
		result.WriteString(fmt.Sprintf("      Size: %d, Index: %d\n", trans.size, atomic.LoadUint32(&trans.index)))

		activeCount := 0
		for i, tr := range trans.cliTransports {
			if tr != nil {
				isActive := tr.(grpc.IsActive).IsActive()
				if isActive {
					activeCount++
				}
				result.WriteString(fmt.Sprintf("        [%d] Active: %v\n", i, isActive))
			} else {
				result.WriteString(fmt.Sprintf("        [%d] <nil>\n", i))
			}
		}
		result.WriteString(fmt.Sprintf("      ActiveCount: %d/%d\n", activeCount, trans.size))
		return true
	})

	return result.String()
}

